<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { Modal, message } from 'ant-design-vue';
import { getShopList, type MallShopApi } from '#/api/mall/product/shop';
import {getShopSettlementPage,getShopSettlement,generateShopSettlement,auditShopSettlement,payShopSettlement,carryShopSettlement,getSettlementProof,settlementStatus,type ShopSettlement,type SettlementDetail} from '#/api/mall/trade/settlement';
const rows=ref<ShopSettlement[]>([]),shops=ref<MallShopApi.Shop[]>([]),shopId=ref<number>(),status=ref<number>(),page=ref(1),total=ref(0),busy=ref(false),error=ref(false);
const prior=new Date();prior.setDate(1);prior.setMonth(prior.getMonth()-1);
const month=ref(prior.getFullYear()+'-'+String(prior.getMonth()+1).padStart(2,'0')),rate=ref(0),detail=ref<SettlementDetail>(),opened=ref(false),remark=ref(''),reference=ref(''),paidAt=ref(''),proof=ref(''),amount=ref('');
const money=(n:number)=>(n/100).toFixed(2);
const time=(value:unknown)=>value?new Date(value as string|number).toLocaleString('zh-CN',{hour12:false}):'-';
async function refresh(){busy.value=true;error.value=false;try{const r=await getShopSettlementPage({pageNo:page.value,pageSize:10,shopId:shopId.value,status:status.value});rows.value=r.list;total.value=r.total}catch{rows.value=[];error.value=true}finally{busy.value=false}}
async function show(row:ShopSettlement){busy.value=true;try{detail.value=await getShopSettlement(row.id);remark.value='';reference.value='';paidAt.value='';proof.value='';amount.value='';opened.value=true}finally{busy.value=false}}
function generate(){if(!shopId.value||busy.value)return;Modal.confirm({title:'生成/重算月度账单',content:'佣金按退款后实付（含运费）逐订单计算；草稿重算会更新版本并保留历史快照。确认月份和佣金率无误？',okText:'确认生成',cancelText:'返回',async onOk(){busy.value=true;try{await generateShopSettlement({shopId:shopId.value!,month:month.value,commissionRate:rate.value});message.success('账单已生成');await refresh()}finally{busy.value=false}}})}
async function audit(approved:boolean){if(!detail.value||busy.value)return;if(!remark.value.trim())return void message.warning('请填写审核或退回原因');busy.value=true;try{await auditShopSettlement({id:detail.value.bill.id,version:detail.value.bill.version,approved,remark:remark.value});opened.value=false;await refresh()}finally{busy.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];proof.value='';if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2097152)return void message.warning('凭证仅支持2MB内PNG/JPEG');const reader=new FileReader();reader.onload=()=>{proof.value=String(reader.result)};reader.readAsDataURL(file)}
function pay(){const b=detail.value?.bill;if(!b||busy.value)return;const cents=Math.round(Number(amount.value)*100);if(!/^\d+(\.\d{1,2})?$/.test(amount.value)||cents!==b.settlementAmount||!reference.value.trim()||!paidAt.value||!proof.value)return void message.warning('金额须等于应结金额，并填写流水、时间、上传凭证');Modal.confirm({title:'确认已完成线下付款？',content:'仅登记真实已付款事实，不会发起自动转账。请核对收款店铺、金额和凭证。',okText:'登记线下付款',cancelText:'返回核对',async onOk(){busy.value=true;try{await payShopSettlement({id:b.id,version:b.version,amount:cents,reference:reference.value.trim(),paidAt:new Date(paidAt.value).getTime(),proof:proof.value});opened.value=false;message.success('线下付款已登记');await refresh()}finally{busy.value=false}}})}
function carry(){const b=detail.value?.bill;if(!b||busy.value)return;Modal.confirm({title:'确认结转余额？',content:'本账单无需付款，负余额将在下期抵扣，不标记为已打款。',okText:'确认结转',cancelText:'返回',async onOk(){busy.value=true;try{await carryShopSettlement(b.id,b.version);opened.value=false;await refresh()}finally{busy.value=false}}})}
async function viewProof(){if(detail.value)proof.value=await getSettlementProof(detail.value.bill.id)}
onMounted(async()=>{await refresh();shops.value=await getShopList()});
</script>
<template><Page auto-content-height><section class="settlement"><h2>正式店铺结算</h2><p>已结束自然月 · 完成收货且无进行中售后的订单 · 同一订单不重复结算 · 真实自动打款未接通</p>
<div class="filters"><select v-model="shopId" :disabled="busy" @change="page=1;refresh()"><option :value="undefined">全部店铺</option><option v-for="shop in shops" :key="shop.id" :value="shop.id">{{shop.name}}</option></select><select v-model="status" :disabled="busy" @change="page=1;refresh()"><option :value="undefined">全部状态</option><option v-for="(name,key) in settlementStatus" :key="key" :value="Number(key)">{{name}}</option></select><input v-model="month" aria-label="结算月份" type="month" :disabled="busy"/><label>佣金万分比 <input v-model.number="rate" type="number" min="0" max="10000" step="1" :disabled="busy"/></label><button :disabled="busy||!shopId" @click="generate">生成/重算账单</button><button :disabled="busy" @click="refresh">刷新</button></div>
<p v-if="error" role="alert">账单读取失败，请重试；不是没有结算数据。</p><table><thead><tr><th>单号</th><th>店铺/月</th><th>订单数</th><th>应结金额（元）</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.no}}</td><td>{{row.shopName}} / {{row.billMonth}}</td><td>{{row.orderCount}}</td><td>{{money(row.settlementAmount)}}</td><td>{{settlementStatus[row.status]}}</td><td><button :disabled="busy" @click="show(row)">查看/处理</button></td></tr></tbody></table><p v-if="!busy&&!error&&!rows.length">暂无结算单</p><div class="filters"><button :disabled="busy||page===1" @click="page--;refresh()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/10))}} 页，共 {{total}} 张</span><button :disabled="busy||page*10>=total" @click="page++;refresh()">下一页</button></div>
<Modal v-model:open="opened" title="结算账单详情" :footer="null" :width="1100" :mask-closable="false"><template v-if="detail"><h3>{{detail.bill.shopName}} / {{detail.bill.billMonth}} / 第{{detail.bill.version}}版</h3><p>{{settlementStatus[detail.bill.status]}} · {{detail.bill.no}}</p><p>实付含运费 {{money(detail.bill.orderPayAmount)}} − 已退款 {{money(detail.bill.refundAmount)}} − 佣金 {{money(detail.bill.commissionAmount)}} + 跨期调整 {{money(detail.bill.adjustmentAmount)}} − 上期抵扣 {{money(detail.bill.carryAmount)}} = 应结 <strong>{{money(detail.bill.settlementAmount)}} 元</strong></p><p>佣金按退款后实付（含运费）计算、逐订单四舍五入到分。跨期退款使用原订单佣金率冲回。此前因售后暂缓的订单可在后续月份补结。</p>
<div class="items"><table><thead><tr><th>订单号</th><th>类型</th><th>实付</th><th>运费（已含）</th><th>累计退款</th><th>佣金/冲回</th><th>本项应结</th></tr></thead><tbody><tr v-for="item in detail.items" :key="item.id"><td>{{item.orderNo}}</td><td>{{item.kind===1?'订单结算':'跨期退款'}}</td><td>{{money(item.payAmount)}}</td><td>{{money(item.deliveryAmount)}}</td><td>{{money(item.refundTotal)}}</td><td>{{money(item.commissionAmount)}}</td><td>{{money(item.amount)}}</td></tr></tbody></table></div>
<p v-if="detail.bill.auditRemark">审核意见：{{detail.bill.auditRemark}}</p><div v-if="[10,20,30].includes(detail.bill.status)"><textarea v-model="remark" placeholder="审核/退回原因（必填）" maxlength="500" :disabled="busy"/><button v-if="detail.bill.status===10" :disabled="busy" @click="audit(true)">审核通过</button><button :disabled="busy" @click="audit(false)">退回重新核算</button></div><p v-if="detail.bill.status===20">等待供应商会员在PC销售中心确认；平台不可代确认。</p>
<div v-if="detail.bill.status===30 && detail.bill.settlementAmount>0" class="payment"><h3>登记已完成的线下付款</h3><input v-model="amount" placeholder="实际付款金额（元）" :disabled="busy"/><input v-model="reference" placeholder="唯一付款流水号" maxlength="100" :disabled="busy"/><input v-model="paidAt" aria-label="实际付款时间" type="datetime-local" step="1" :disabled="busy"/><label>私有付款凭证（PNG/JPEG ≤2MB）<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="upload"/></label><button :disabled="busy" @click="pay">登记线下付款</button></div><button v-if="detail.bill.status===30 && detail.bill.settlementAmount<=0" :disabled="busy" @click="carry">结转余额（无需付款）</button>
<p v-if="detail.bill.paymentReference">付款流水：{{detail.bill.paymentReference}} / {{time(detail.bill.paymentTime)}}</p><button v-if="detail.bill.status===40" @click="viewProof">查看私有付款凭证</button><img v-if="proof" :src="proof" alt="付款凭证" style="max-width:100%;max-height:380px"/><h3>操作记录</h3><p v-for="(log,i) in detail.logs" :key="i">版本{{log.version}} · {{time(log.createTime)}} · {{log.remark}}</p></template></Modal></section></Page></template>
<style scoped>.settlement{padding:24px}h2{font-size:22px}p{margin:14px 0}.filters,.payment{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}input,select,textarea,button{padding:8px;border:1px solid #aab3bd;border-radius:4px}button{color:#1677ff}button:disabled{opacity:.45;cursor:not-allowed}table{width:100%;text-align:left}td,th{padding:12px;border-bottom:1px solid #e5e7eb}textarea{display:block;width:100%;margin:12px 0}.items{max-height:350px;overflow:auto}</style>

